  'A document': 'ஒரு ஆவணம்',
  'A PDF, as pages to write on': 'ஒரு PDF, எழுதும் பக்கங்களாக',
  'Undo the import': 'இறக்குமதியைச் செயல்தவிர்',
  'Choose an export': 'ஏற்றுமதியைத் தேர்ந்தெடு',
  Under: 'இதன் கீழ்',
  Sync: 'ஒத்திசை',
