  'Your AI provider': 'உங்கள் AI வழங்குநர்',
  'Stays on this computer': 'இந்தக் கணினியிலேயே இருக்கும்',
  'Audio goes to {host}': 'ஒலி {host}-க்குச் செல்கிறது',
