    'இந்தச் சாதனத்தின் முன் இருக்கும் ஒருவரை PIN தடுக்கும். உங்கள் பெயரில் இயங்கும் ஒரு நிரலை அது தடுக்காது; அந்த நிரல் முத்திரையைப் படித்து ஒவ்வொரு PIN-ஐயும் முயலலாம்.',
