  'New recovery key': 'புதிய மீட்புச் சாவி',
  'The old key still opens a copy of Pass somebody kept from before.':
    'யாரோ முன்பே வைத்திருக்கும் Pass நகலைப் பழைய சாவி இன்னும் திறக்கும்.',
  'Set up Pass': 'Pass-ஐ அமை',
  'Your Pass password encrypts everything in Pass. Nobody can reset it for you.':
    'உங்கள் Pass கடவுச்சொல் Pass-இல் உள்ள அனைத்தையும் மறையாக்குகிறது. அதை உங்களுக்காக யாராலும் மீட்டமைக்க முடியாது.',
  'Setting up…': 'அமைக்கிறது…',
  'Pass could not be set up.': 'Pass-ஐ அமைக்க முடியவில்லை.',
  'Invitation sent to {email}': '{email}-க்கு அழைப்பு அனுப்பப்பட்டது',
  'The vault gets a new key. What they kept from before stays readable to them.':
    'பெட்டகத்துக்குப் புதிய சாவி கிடைக்கும். அவர்கள் முன்பே வைத்திருப்பவை அவர்களுக்குப் படிக்கக்கூடியதாகவே இருக்கும்.',
  'Transfer ownership to': 'உரிமையை யாருக்கு மாற்றுவது',
  'Make {name} the owner?': '{name}-ஐ உரிமையாளர் ஆக்கவா?',
  'You stay a manager of the vault.': 'நீங்கள் பெட்டகத்தின் மேலாளராகத் தொடர்வீர்கள்.',
  Transfer: 'மாற்று',
  'Leave {vault}?': '{vault}-ஐ விட்டு வெளியேறவா?',
  'Its items leave this device. Somebody who manages it can invite you again.':
    'அதன் உருப்படிகள் இந்தச் சாதனத்திலிருந்து நீங்கும். அதை நிர்வகிப்பவர் உங்களை மீண்டும் அழைக்கலாம்.',
  'They have not set up Pass yet. Confirm them here once they have.':
    'அவர்கள் இன்னும் Pass-ஐ அமைக்கவில்லை. அமைத்ததும் இங்கே அவர்களை உறுதிப்படுத்து.',
  'Their key is not the one this device knew. Check their safety code with them again.':
    'அவர்களின் சாவி இந்தச் சாதனம் அறிந்தது அல்ல. அவர்களுடன் பாதுகாப்புக் குறியீட்டை மீண்டும் சரிபார்.',
  'Safety code': 'பாதுகாப்புக் குறியீடு',
  'Codes match': 'குறியீடுகள் பொருந்துகின்றன',
  'Share {vault}': '{vault}-ஐப் பகிர்',
  'Pass gives them the vault’s key when you invite them.':
    'நீங்கள் அழைக்கும்போது Pass அவர்களுக்குப் பெட்டகத்தின் சாவியைத் தரும்.',
  'Read it to them. Only once you press Codes match does Pass give them the vault’s key.':
    'அதை அவர்களுக்குப் படித்துக் காட்டு. நீங்கள் “குறியீடுகள் பொருந்துகின்றன” என்பதை அழுத்திய பின்னரே Pass அவர்களுக்குப் பெட்டகத்தின் சாவியைத் தரும்.',
